public class EnumTest {
    private enum Status { CONTINUE, WON, LOST };

    public static void main(String[] args) {
        int gameStatus = 1;
        if (gameStatus == Status.WON) {
            System.out.println("Player wins");
        } else {
            System.out.println("Keep playing");
        }
    }
}

public class OverloadTest {
    public static void printVal(int x) {
        System.out.print("Int: " + x);
    }

    public static void printVal(double x) {
        System.out.print("Double: " + x);
    }

    public static void main(String[] args) {
        printVal(7);
    }
}

public class ScopeTest {
    public static void main(String[] args) {
        for (int i = 0; i < 2; i++) {
            int x = i * 2;
        }
        System.out.println(x);
    }
}

import java.security.SecureRandom;

public class RandomTest {
    public static void main(String[] args) {
        SecureRandom random = new SecureRandom();
        int val = random.nextInt(1);
        System.out.println(val + 5);
    }
}

public class ConcatTest {
    public static void main(String[] args) {
        int a = 3;
        int b = 4;
        System.out.println(a + b + " and " + a + b);
    }
}

public class PromotionTest {
    public static void print(double x) {
        System.out.print("double: " + x);
    }

    public static void print(float x) {
        System.out.print("float: " + x);
    }

    public static void main(String[] args) {
        int a = 5;
        print((float) a + 0.5);
    }
}

public class ShadowTest {
    private static int x = 10;

    public static void modify() {
        int x = 5;
        x *= 2;
    }

    public static void main(String[] args) {
        modify();
        System.out.println(x);
    }
}

public class OverloadTrap {
    public static int calculate(int x, int y) {
        return x + y;
    }

    public static double calculate(int a, int b) {
        return a * b;
    }

    public static void main(String[] args) {
        System.out.println(calculate(2, 3));
    }
}

public class StackTest {
    public static int factorial(int n) {
        if (n == 0) {
            return 1;
        }
        return n * factorial(n);
    }

    public static void main(String[] args) {
        System.out.println(factorial(3));
    }
}
